// Format emails for AI summarization
const emails = $input.all();

const formattedEmails = emails.map((email, index) => {
  const data = email.json;

  // Extract email link (Gmail message ID)
  const messageId = data.id;
  const emailLink = `https://mail.google.com/mail/u/0/#inbox/${messageId}`;

  return {
    number: index + 1,
    from: data.from?.name || data.from?.address || 'Unknown',
    fromEmail: data.from?.address || '',
    subject: data.subject || '(No subject)',
    snippet: data.snippet || data.textPlain?.substring(0, 200) || '',
    date: data.date || '',
    link: emailLink,
    messageId: messageId
  };
});

// Create prompt for AI
const emailTexts = formattedEmails.map(email => 
  `Email ${email.number}:
  From: ${email.from} (${email.fromEmail})
  Subject: ${email.subject}
  Preview: ${email.snippet}
  Link: ${email.link}`
).join('\n\n');

return {
  emails: formattedEmails,
  totalCount: formattedEmails.length,
  promptText: emailTexts,
  date: new Date().toLocaleDateString('en-US', { 
    weekday: 'long', 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric' 
  })
};

